using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SpreadEssenceAction", menuName = "Data/Battle/Battle Actions/Sothis/SpreadEssence Action")]
public class SpreadEssenceAction : MultipleSoulHeatTierAction
{
	[Header("Effects")]
	[SerializeField]
	private Effect effectToSpread;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	public override bool CheckCondition(GameObject target, int actionValue)
	{
		if (GetSoulHeatAmountToUse(activateFeedback: true) >= actionValue)
		{
			return target.GetComponent<UnitEffects>().IsEffectActiveGetAmount(effectToSpread, activateFeedback: false) > 0;
		}
		return true;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		CastMultipleSoulHeatTierFirstActionSoulHeatVariableAction(delegate
		{
			if (IsVFXEnabled())
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DefaultCastVFXDelay(target, amount, source));
				ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			}
			else
			{
				ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
				DefaultCast(target, amount, source);
			}
		}, delegate
		{
			secondBattleAction.CastTargetAmount(target, secondActionValue, source);
		}, null, amount, source);
	}

	private IEnumerator DefaultCastVFXDelay(GameObject target, int amount, GameObject source)
	{
		PlaySFX();
		SpawnVFX(GetVFXOwnerPosition(target), 4f);
		yield return new WaitForSeconds(vfxDelay);
		DefaultCast(target, amount, source);
	}

	private void DefaultCast(GameObject target, int amount, GameObject source)
	{
		int num = target.GetComponent<UnitEffects>().IsEffectActiveGetAmount(effectToSpread);
		if (num > 0)
		{
			for (int i = 0; i < currentActiveUnits.GetCurrentActiveUnits().Count; i++)
			{
				GameObject gameObject = currentActiveUnits.GetCurrentActiveUnits()[i];
				if (gameObject != target)
				{
					gameObject.GetComponent<UnitEffects>().AddEffect(effectToSpread, num);
				}
			}
		}
		ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
	}
}
